import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

interface Manutencao {
  id: number;
  titulo: string;
  local: string;
  setor: string;
  descricao: string;
  prioridade: 'alta' | 'media' | 'baixa';
  data_criacao: string;
}

interface ManutencoesPorPrioridade {
  alta: Manutencao[];
  media: Manutencao[];
  baixa: Manutencao[];
}

export default function TecnicoDashboard() {
  const { token } = useParams<{ token: string }>();
  const navigate = useNavigate();
  const [tecnico, setTecnico] = useState<{ nome: string; email: string } | null>(null);
  const [manutencoes, setManutencoes] = useState<ManutencoesPorPrioridade>({
    alta: [],
    media: [],
    baixa: []
  });
  const [mensagem, setMensagem] = useState<{ tipo: 'sucesso' | 'erro'; texto: string } | null>(null);

  useEffect(() => {
    if (!token) {
      navigate('/');
      return;
    }

    const validarAcesso = async () => {
      try {
        const response = await axios.get(`http://localhost:3001/api/tecnicos/acesso/${token}`);
        setTecnico(response.data);
        carregarManutencoes();
      } catch (error) {
        navigate('/');
      }
    };

    validarAcesso();
  }, [token, navigate]);

  const carregarManutencoes = async () => {
    try {
      const response = await axios.get(`http://localhost:3001/api/tecnicos/manutencoes/${token}`);
      setManutencoes(response.data);
    } catch (error) {
      console.error('Erro ao carregar manutenções:', error);
    }
  };

  const handleConcluirManutencao = async (id: number) => {
    try {
      await axios.patch(`http://localhost:3001/api/tecnicos/manutencoes/${token}/${id}/concluir`);
      setMensagem({ tipo: 'sucesso', texto: 'Manutenção marcada como concluída!' });
      carregarManutencoes();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao concluir manutenção' });
    }
  };

  const renderManutencoes = (manutencoes: Manutencao[], prioridade: string) => {
    if (manutencoes.length === 0) {
      return (
        <p className="text-sm text-gray-500 italic">
          Nenhuma manutenção com prioridade {prioridade.toLowerCase()}
        </p>
      );
    }

    return manutencoes.map(manutencao => (
      <div
        key={manutencao.id}
        className={`border rounded-lg p-4 ${
          manutencao.prioridade === 'alta'
            ? 'border-red-200 bg-red-50'
            : manutencao.prioridade === 'media'
            ? 'border-yellow-200 bg-yellow-50'
            : 'border-green-200 bg-green-50'
        }`}
      >
        <h3 className="font-medium">{manutencao.titulo}</h3>
        <p className="text-sm text-gray-600">Local: {manutencao.local}</p>
        <p className="text-sm text-gray-600">Setor: {manutencao.setor}</p>
        {manutencao.descricao && (
          <p className="text-sm text-gray-600 mt-2">{manutencao.descricao}</p>
        )}
        <p className="text-sm text-gray-500 mt-2">
          Data: {new Date(manutencao.data_criacao).toLocaleDateString()}
        </p>
        <button
          onClick={() => handleConcluirManutencao(manutencao.id)}
          className="mt-4 px-4 py-2 text-sm text-white bg-primary-600 rounded hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
        >
          Marcar como Concluída
        </button>
      </div>
    ));
  };

  if (!tecnico) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <nav className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-semibold text-gray-900">
                Painel do Técnico - {tecnico.nome}
              </h1>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        {mensagem && (
          <div className={`mb-4 rounded-md p-4 ${
            mensagem.tipo === 'sucesso' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
          }`}>
            <p className="text-sm">{mensagem.texto}</p>
          </div>
        )}

        <div className="space-y-6">
          {/* Alta Prioridade */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-red-600 mb-4">
              Alta Prioridade
            </h2>
            <div className="space-y-4">
              {renderManutencoes(manutencoes.alta, 'Alta')}
            </div>
          </div>

          {/* Média Prioridade */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-yellow-600 mb-4">
              Média Prioridade
            </h2>
            <div className="space-y-4">
              {renderManutencoes(manutencoes.media, 'Média')}
            </div>
          </div>

          {/* Baixa Prioridade */}
          <div className="bg-white shadow rounded-lg p-6">
            <h2 className="text-lg font-medium text-green-600 mb-4">
              Baixa Prioridade
            </h2>
            <div className="space-y-4">
              {renderManutencoes(manutencoes.baixa, 'Baixa')}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
